function db.gainXp(OD,PD)
local QD,RD=tonumber(OD.xp)or 0,db.xpFor(OD.unit_id,db.cap(OD))
local SD=math.max(0,RD-QD)
if SD<=0 or(PD or 0)<=0 then
return 0,0
end
local TD=math.min(PD,SD)
local UD=db.base(OD)
if UD<=0 then
return 0,TD
end
return db.share(OD.unit_id)*(db.score(db.whatIf(OD,{xp=QD+TD}))/UD-1)*100,TD
end
function db.gainFuse(VD)
if db.lb(VD)>=1 then
return 0
end
local WD=db.base(VD)
if WD<=0 then
return 0
end
local XD=db.whatIf(VD,{xp=math.max(tonumber(VD.xp)or 0,db.xpFor(VD.unit_id,110)),further_modifiers={limit_break={current_limit_break=1}}})
return db.share(VD.unit_id)*(db.score(XD)/WD-1)*100+5
end
