function db.relicWorth(YD,ZD)
local _D=ZD._unique_item_data and ZD._unique_item_data._unique_relic_data
if not _D then
return 0
end
local aE=H.Items[ZD.item_id]or{}
local bE,cE=N.types(YD.unit_id)
if aE.main_damage_type and aE.main_damage_type~=hoc[1886]and aE.main_damage_type~=cE then
return 0
end
local dE,eE=0,0
for fE,gE in pairs(_D._core_damage_type_buffs or{})do
if bE[gE.damage_type]then
dE=dE+(tonumber(gE.mul)or 0)+(tonumber(gE.add_upg)or 0)*0.01+(tonumber(gE.pen)or 0)*0.001
eE=eE+(tonumber(gE.crit)or 0)
end
end
dE=dE+eE*0.5
local hE=N.rows(YD.unit_id)
local iE=hE and hE[hE.max]
local jE=(iE and tonumber(iE.cd)or 0)*N.mult(YD,hoc[1538])
for kE,lE in pairs(_D._unique_relic_effects or{})do
local mE=type(lE.params)==hoc[1404]and lE.params or{}
if lE.id==hoc[1887]then
local nE=math.min(1,(tonumber(mE.extra_damage)or 0)*jE/math.max(1,tonumber(mE.time_interval)or 40))
local oE=N.DRONES and N.DRONES[YD.unit_id]
if oE and oE.late and jE>0 then
local pE=1/jE
nE=nE*pE/(pE+(tonumber(oE.max)or 0)*(tonumber(oE.late.dmg)or 0)*(tonumber(oE.hits)or 1)/math.max(0.1,tonumber(oE.late.cd)or 4))
end
dE=dE+nE
elseif lE.id==hoc[1888]then
dE=dE+(tonumber(mE.dmg_buff)or 0)*0.25
elseif lE.id==hoc[1889]then
dE=dE+(tonumber(mE.dmg_buff)or 0)*eE
elseif lE.id==hoc[1890]then
if bE.magic then
dE=0
else
dE=dE+(tonumber(mE.dmg_buff)or 0)*0.3
end
elseif lE.id==hoc[1891]then
if bE.water_damage then
dE=dE+0.05
end
end
end
return dE
end
