function Q.buildPath()
Q.samples={}
local pwb=H.PATH and H.PATH.PATH_CACHE and H.PATH.PATH_CACHE[workspace._BASES.pve]
if not pwb then
return
end
for qwb,rwb in pairs(pwb)do
if not(H.PATH.HIDDEN_MOCK_LANES and H.PATH.HIDDEN_MOCK_LANES[qwb.Name])then
local swb={}
for twb,uwb in ipairs(rwb.points or{})do
table.insert(swb,uwb.part.Position)
end
local vwb=0
for wwb=2,#swb do
vwb=vwb+(swb[wwb]-swb[wwb-1]).Magnitude
end
local xwb=0
for ywb=2,#swb do
local zwb,Awb=swb[ywb-1],swb[ywb]
local Bwb=(Awb-zwb).Magnitude
local Cwb=math.max(1,math.floor(Bwb/2))
for Dwb=0,Cwb-1 do
local Ewb=zwb:Lerp(Awb,Dwb/Cwb)
table.insert(Q.samples,{pos=Ewb,prog=(xwb+Bwb*Dwb/Cwb)/math.max(1,vwb),lane=qwb.Name})
end
xwb=xwb+Bwb
end
if swb[#swb]then
table.insert(Q.samples,{pos=swb[#swb],prog=1,lane=qwb.Name})
end
end
end
local Fwb,Gwb,Hwb={},0,0
for Iwb,Jwb in ipairs(Q.samples)do
local Kwb=tostring(Jwb.lane)
if not Fwb[Kwb]then
Gwb=Gwb+1
end
Fwb[Kwb]=(Fwb[Kwb]or 0)+1
Hwb=Hwb+1
end
Q.laneCount={n=Gwb,by=Fwb,avg=Gwb>0 and Hwb/Gwb or 1}
end
