local TNb=Q.buffShort(SNb)
local UNb=J.stack[SNb.attack]
local VNb=UNb and UNb.stacks and(UNb.cap or 1)or nil
local WNb,XNb=pcall(N.range,RNb.u,0)
XNb=(WNb and tonumber(XNb)or 15)*((Q.info and tonumber(Q.info.rangeScale))or 1)
local YNb=0
for ZNb,_Nb in ipairs(TNb)do
local aOb=0
for bOb,cOb in ipairs(TNb)do
if(cOb.pos-_Nb.pos).Magnitude<=XNb then
local dOb=SNb.types[cOb.base]
local eOb=dOb*SNb.uptime
if VNb then
eOb=math.max(0,math.min(VNb,(cOb.n+1)*dOb*SNb.uptime)-math.min(VNb,cOb.n*dOb*SNb.uptime))
