local bVb=math.max(0.02,0.25*math.sqrt(30/(30+aVb.n)))
local cVb=M.clamp(ZUb/_Ub,0.3,3)
Q.lastEff[XUb]=math.floor(cVb*1000+0.5)/1000
aVb.eff=aVb.eff+(cVb-aVb.eff)*bVb
